head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 호출 화면에서 전달한 팝업 파라미터(콜백 함수 포함)를 수신한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
    try {
        scwin.param = $c.data.getParameter();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "popup_roadZipcode.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/// EVENT ///

/**
 * @method
 * @name rd_searchType_onviewchange
 * @description 검색조건 변경 — 검색결과·입력값을 초기화하고 검색구분(1:도로명, 2:건물명, 3:직접입력)에 따라 검색조건·안내문구·조회버튼 표시를 전환한다.
 * @param {Object} info 이벤트 정보 객체(value: 변경된 검색구분 값)
 * @returns {void}
 * @hidden N
 * @example scwin.rd_searchType_onviewchange(info);
 */
scwin.rd_searchType_onviewchange = function (info) {
    try {
        const type = info.value;

        scwin.searchResult(false); // 검색 초기화
        dma_Req.setEmptyValue(); // 입력 초기화
        dma_Req.set("searchType", type);

        if(type === "1") {
            // 검색조건
            grp_search1.show("");
            grp_search2.hide();
            grp_search3_1.hide();
            grp_search3_2.hide();

            // 안내문구
            grp_info1.show("");
            grp_info2.hide();
            grp_info3.hide();

            // 조회버튼
            btn_search.show("");
        } else if(type === "2") {
            // 검색조건
            grp_search1.hide();
            grp_search2.show("");
            grp_search3_1.hide();
            grp_search3_2.hide();

            // 안내문구
            grp_info1.hide();
            grp_info2.show("");
            grp_info3.hide();

            // 조회버튼
            btn_search.show("");

        } else if(type === "3") {
            // 검색조건
            grp_search1.hide();
            grp_search2.hide();
            grp_search3_1.show("");
            grp_search3_2.show("");

            // 안내문구
            grp_info1.hide();
            grp_info2.hide();
            grp_info3.show("");

            // 조회버튼
            btn_search.hide();
        }

    } catch (ex) {
        $c.exception.handleError(ex, { context : "popup_roadZipcode.rd_searchType_onviewchange" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description [조회] 버튼 클릭 — 필수값 검증 후 우편번호 목록을 조회하고, 검증 실패 시 해당 입력란으로 포커스를 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_search_onclick(e);
 */
scwin.btn_search_onclick = async function (e) {
    try {
        const type = rd_searchType.getValue();
        if(scwin.checkValues(type)) {
            const sbmOptions = {
                id : "sbm_SelectRoadZip",
                action : "/api/discls/common/popup/misc/zipcd/select-list",
                method : "get",
                ref : "dma_Req",
                target : "dlt_AddrListRes=body",
                gridview : "grd_Grid",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            scwin.sbm_SelectRoadZip_submitdone(sbmRtn);

        } else {
            if(type === "1") {
                ipt_raodNm1.focus();
            } else if(type === "2") {
                ipt_bldgNo.focus();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "popup_roadZipcode.btn_search_onclick" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 직접입력 [확인] 버튼 클릭 — 직접입력한 우편번호·주소 입력값 검증을 수행한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_confirm_onclick(e);
 */
scwin.btn_confirm_onclick = function (e) {
    try {
        scwin.otherZipCodeChk();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "popup_roadZipcode.btn_confirm_onclick" });
    }
};

/**
 * @method
 * @name btn_cancel_onclick
 * @description [닫기] 버튼 클릭 — 팝업을 닫는다.
 * @returns {void}
 * @hidden N
 * @example scwin.btn_cancel_onclick();
 */
scwin.btn_cancel_onclick = function () {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "popup_roadZipcode.btn_cancel_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_oncellclick
 * @description row 선택 — 선택한 행의 우편번호·도로명주소를 호출 화면으로 전달한다.
 * @param {Number} rowIndex 클릭한 행 인덱스
 * @param {Number} columnIndex 클릭한 컬럼 인덱스
 * @param {String} columnId 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.grd_Grid_oncellclick(rowIndex, columnIndex, columnId);
 */
scwin.grd_Grid_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        const rowData = dlt_AddrListRes.getRowJSON(rowIndex);
        if(rowData && rowData.zipCd && rowData.roadAddr) {
            scwin.setZipCodePop(rowData.zipCd, rowData.roadAddr);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "popup_roadZipcode.grd_Grid_oncellclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/// SUBMISSION ///
/**
 * @method
 * @name sbm_SelectRoadZip_submitdone
 * @description 우편번호 조회 완료 콜백 — 조회 결과 유무에 따라 목록을 표시(주소 포맷 적용)하거나 안내 메시지를 노출한다.
 * @param {Object} e 서브미션 응답 객체(responseJSON 포함)
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_SelectRoadZip_submitdone(sbmRtn);
 */
scwin.sbm_SelectRoadZip_submitdone = function (e) {
    const res = e.responseJSON;
    if(res.body && res.body.length > 0) {
        scwin.searchResult(true);
        scwin.fmtAddr(res.body);

    } else {
        scwin.searchResult(false);        
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/// FUNCTION ///

/**
 * @method
 * @name fmtAddr
 * @description row에 표시되는 주소 컬럼 포맷 — 도로명주소·지번주소를 조합한 HTML을 표시용 컬럼(displayAddr)에 설정한다.
 * @param {Array} resList 조회된 주소 목록
 * @returns {void}
 * @hidden N
 * @example scwin.fmtAddr(res.body);
 */
scwin.fmtAddr = function (resList) {
    dlt_AddrListRes.setBroadcast(false);
    for (let i = 0; i < resList.length; i++) {
        const item = resList[i];
        let addr = "<span class='txt_blue'>"+item.roadAddr+"</span>";
        addr += "</br>";
        addr += "<span style='padding: 0 4px;'> "+item.jibunAddr+"</span>";

        dlt_AddrListRes.setCellData(i, "displayAddr", addr);
    }
    dlt_AddrListRes.setBroadcast(true, true);
};

/**
 * @method
 * @name searchResult
 * @description 검색결과 표시 — 결과가 있으면 목록 영역을, 없으면 안내 메시지 영역을 표시한다.
 * @param {Boolean} isResult 검색결과 존재 여부
 * @returns {void}
 * @hidden N
 * @example scwin.searchResult(true);
 */
scwin.searchResult = function (isResult) {
    if(isResult) {
        grp_zipLoad.show("");
        grp_resMsgBox.hide();

    } else {
        txt_message.setValue("조회 내역이 없습니다.");
        grp_zipLoad.hide();
        grp_resMsgBox.show("");
    }
};

/**
 * @method
 * @name checkValues
 * @description 조회 필수값 검증 — 검색구분별 필수 입력값(도로명/건물명)·최소 글자수·특수문자(%) 사용 여부를 검증한다.
 * @param {String} type 검색구분(1:도로명, 2:건물명)
 * @returns {Boolean} 검증 통과 여부
 * @hidden N
 * @example scwin.checkValues("1");
 */
scwin.checkValues = function (type) {
    if(type === "1") { // 도로명 검색
        const roadNm = ipt_raodNm1.getValue();
        const bldgNo = ipt_bldgNo.getValue();
        if(!roadNm) {
            alert ('검색할 도로명을 입력해 주세요.');
            return false;
        } else if(roadNm.length < 2) {
            alert('도로명은 두글자 이상 입력되어야 합니다.');
            return false;
        } else if(scwin.specialWord(roadNm) || scwin.specialWord(bldgNo)) {
            alert('%는 사용 할 수 없습니다.');
            return false;
        } else {
            return true;
        }

    } else if(type === "2") { // 건물명 검색
        const roadNm = ipt_raodNm2.getValue();
        const bldgNm = ipt_bldgNm.getValue();
        if(!bldgNm) {
            alert('검색할 건물명을 입력해 주세요.');
            return false;
        } else if(bldgNm.length < 2) {
            alert('건물명은 두글자 이상 입력되어야 합니다.');
            return false;
        } else if(scwin.specialWord(bldgNm) || scwin.specialWord(roadNm)) {
            alert('%는 사용 할 수 없습니다.');
            return false;
        } else {
            return true;
        }

    } else {
        alert("검색조건을 선택하세요.");
        return false;
    }
};

/**
 * @method
 * @name specialWord
 * @description 특수문자(%) 사용 검증 - 전체조회 방지
 * @param {String} str 검사할 문자열
 * @returns {Boolean} %가 포함되어 있으면 true, 빈값이면 false
 * @hidden N
 * @example scwin.specialWord(roadNm);
 */
scwin.specialWord = function (str) {
    const reg = /%/;
    if (str === null || str === ""){
        return false;
    }
    if(reg.test(str)){
        return true;	
    }
};

/**
 * @method
 * @name otherZipCodeChk
 * @description 직접입력 입력값 검증 — 우편번호(숫자 또는 -)·주소 입력값을 검증한 후 호출 화면으로 전달한다.
 * @returns {void}
 * @hidden N
 * @example scwin.otherZipCodeChk();
 */
scwin.otherZipCodeChk = function () {
    const zipNo = ipt_zipCode.getValue();
    const addr = ipt_addr.getValue();
    if(!zipNo) {
        alert("우편번호를 입력해 주세요.");
        ipt_zipCode.focus();
        return;
    }

    if(/[^0123456789]/g.test(zipNo)) {

        if(zipNo !== "-") {
            alert("우편번호는 숫자 또는 -만 가능합니다.");
            ipt_zipCode.focus();
            return;
        }
    }

    if(!addr) {
        alert("주소를 입력해 주세요.");
        ipt_addr.focus();
        return;
    }

    scwin.setZipCodePop(zipNo, addr);
};

/**
 * @method
 * @name setZipCodePop
 * @description 데이터 콜백(팝업 닫고 파라미터 전달) — 우편번호·주소를 호출 화면 콜백 함수로 전달하며 팝업을 닫는다.
 * @param {String} zipNo 우편번호
 * @param {String} addr 주소
 * @returns {void}
 * @hidden N
 * @example scwin.setZipCodePop("04538", "서울특별시 중구 소공로 38");
 */
scwin.setZipCodePop = function (zipNo, addr) {
    $c.win.closePopup({"zipNo":zipNo, "addr":addr, "req": scwin.param.data}, scwin.param.callbackFn);
};
